// In nimbus-eth2, the execution block header is always constructed with hardcoded EMPTY_UNCLE_HASH.
// The consensus layer does not support ommers - all post-merge execution blocks must have empty ommers.
func toExecutionBlockHeader(
    payload: ForkyExecutionPayload,
    parentRoot: Opt[Eth2Digest],
    requestsHash = Opt.none(EthHash32)): EthHeader =
  ...
  EthHeader(
    ...
    ommersHash            : EMPTY_UNCLE_HASH,  // Always hardcoded, never derived from payload
    ...)
